/* Convert an HkiManifest into the shape sample-engine consumes from INSTRUMENTS.
   The synthesized object has the same surface as a static entry, with:
     - source: 'hki' marker (sample-engine branches on this to load from
       IndexedDB instead of fetching baseUrl)
     - no baseUrl / ext / filePattern (each sample carries its archive-relative
       `file` field, matching how multi-pattern CDN entries already work)
   The same per-sample fields (segments, trend, trimStart, gain, file) flow
   through unchanged, so the engine's overlay logic doesn't need to know
   whether an instrument is imported or static. */
function manifestToInstrument(m: HkiManifest): any {
  const entry: any = {
    name: m.name,
    source: 'hki',
    baseUrl: '',
    ext: '',
    releaseTime: m.releaseTime,
    volume: m.volume,
    loop: m.loop,
    decays: m.decays,
    samples: m.samples,
  };
  if (m.transpose) entry.transpose = m.transpose;
  if (m.replayOnTranspose) entry.replayOnTranspose = true;
  if (m.vibrato) entry.vibrato = true;
  return entry;
}

/* Lazy synthesis cache. We don't want to rebuild the entry object on every
   `INSTRUMENTS[key]` access (the engine reads through it on every note-on),
   but we DO want it to reflect a re-imported manifest. Keyed by manifest
   reference identity from the registry — when removeBundle/importBundle
   replace the cached record, the manifest reference changes and we re-synth. */
const importedCache = new WeakMap<HkiManifest, any>();
function getImportedEntry(key: string): any | undefined {
  const m = getImportedManifest(key);
  if (!m) return undefined;
  let entry = importedCache.get(m);
  if (!entry) { entry = manifestToInstrument(m); importedCache.set(m, entry); }
  return entry;
}

/* Runtime-imported CDN config → INSTRUMENTS entry. Same shape rules as
   manifestToInstrument: strip analyzer-only metadata (instrumentKey,
   editorState, provenance, noteSemis) and emit only what the engine
   reads. NO `source` field — the engine's CDN-fetch path is the default
   branch, so omitting `source` puts runtime CDN configs on the same
   code path as compile-time entries in STATIC_INSTRUMENTS. */
function configToInstrument(cfg: CdnInstrumentConfig): any {
  const entry: any = {
    name: cfg.name,
    baseUrl: cfg.baseUrl,
    ext: cfg.ext,
    filePattern: cfg.filePattern,
    releaseTime: cfg.releaseTime,
    volume: cfg.volume,
    loop: cfg.loop,
    decays: cfg.decays,
    samples: cfg.samples,
  };
  if (cfg.filePatterns) entry.filePatterns = cfg.filePatterns;
  if (cfg.transpose != null) entry.transpose = cfg.transpose;
  if (cfg.vibrato) entry.vibrato = true;
  if (cfg.replayOnTranspose) entry.replayOnTranspose = true;
  return entry;
}

/* Lazy synthesis cache for CDN-config imports, mirrors importedCache.
   Keyed by config record reference identity — re-import replaces the
   stored CdnInstrumentConfig object, which invalidates the cache entry
   automatically (new reference → no hit). */
const cdnConfigCache = new WeakMap<CdnInstrumentConfig, any>();
function getCdnConfigEntry(key: string): any | undefined {
  const cfg = getImportedCdnConfig(key);
  if (!cfg) return undefined;
  let entry = cdnConfigCache.get(cfg);
  if (!entry) { entry = configToInstrument(cfg); cdnConfigCache.set(cfg, entry); }
  return entry;
}

/* Read-transparent proxy: every consumer that did `INSTRUMENTS[key]` keeps
   working with zero change. Resolution chain: HKI imports → static → CDN
   config imports. A .hki import OVERRIDES a static entry with the same key —
   importing is explicit user intent (e.g. auditioning a MusiQuest bundle
   whose key collides with a shipped instrument), and removing the import
   restores the static fallback. CDN config imports stay BELOW static on
   purpose: they arrive via Analyzer "Send to HKL" and can linger in
   IndexedDB long after the session that sent them — a stale send must not
   silently shadow a shipped instrument. */
export const INSTRUMENTS: Record<string, any> = new Proxy(STATIC_INSTRUMENTS, {
  get(target, prop, _receiver) {
    if (typeof prop !== 'string') return Reflect.get(target, prop);
    const hki = getImportedEntry(prop);
    if (hki) return hki;
    if (prop in target) return target[prop];
    return getCdnConfigEntry(prop);
  },
  has(target, prop) {
    if (typeof prop !== 'string') return Reflect.has(target, prop);
    return (prop in target) || hasImported(prop) || hasImportedCdnConfig(prop);
  },
});
